def delete_cgroup_config(user_id, delete_type=None):
    try:
        delete_type_list = ['backtest_cpu', 'backtest_memory', 'trade_cpu', 'trade_memory', 'notebook_cpu', 'notebook_memory']
        if delete_type is not None:
            if delete_type not in delete_type_list:
                system_log.error('不支持的删除类型：{}'.format(delete_type))
                return None
            else:
                delete_type_list = [delete_type]
                container_id = get_container_id(user_id)
                for delete_type in delete_type_list:
                    scenarios_type, resource_type = delete_type.split('_')
                    if scenarios_type == 'backtest':
                        pre_message = '回测'
                    elif scenarios_type == 'trade':
                        pre_message = '交易'
                    else:
                        pre_message = '研究'
                    if resource_type == 'cpu':
                        post_message = 'CPU'
                    else:
                        post_message = '内存'
                    if container_id is None:
                        if os.path.exists('/sys/fs/cgroup/{}/{}_{}'.format(resource_type, user_id, scenarios_type)):
                            os.system('sudo cgdelete -g {}:{}_{}'.format(resource_type, user_id, scenarios_type))
                            system_log.info('用户 {} 删除{}{}CGroup控制组成功'.format(user_id, pre_message, post_message))
                        continue
                    elif os.path.exists('/sys/fs/cgroup/{}/docker/{}/{}'.format(resource_type, container_id, scenarios_type)):
                        os.system('sudo cgdelete -g {}:/docker/{}/{}'.format(resource_type, container_id, scenarios_type))
                        system_log.info('用户 {} 删除{}{}CGroup控制组成功'.format(user_id, pre_message, post_message))
    except BaseException:
        system_log.error('用户 {} 删除CGroup配置失败，错误原因：{}'.format(user_id, get_traceback_message()))
        return None
