def set_global_cgroup_config():
    try:
        if GLOBAL_CPU_SWITCH == 1:
            if not os.path.exists('/sys/fs/cgroup/cpu/qtglobal'):
                os.system('sudo cgcreate -t root:root -a root:root -g cpu:qtglobal')
                os.system('sudo chmod -R 777 /sys/fs/cgroup/cpu/qtglobal')
                os.system('sudo chown -R fly:fly /sys/fs/cgroup/cpu/qtglobal')
            cpu_count = psutil.cpu_count()
            os.system('sudo echo {} > /sys/fs/cgroup/cpu/qtglobal/cpu.cfs_quota_us'.format(int(GLOBAL_CPU_SIZE * cpu_count * 1000)))
            system_log.info('设置全局CPU CGroup配置成功')
            return None
        else:
            delete_global_cgroup_config()
    except BaseException:
        system_log.error('设置全局CPU CGroup控制组失败，错误原因：{}'.format(get_traceback_message()))
        return None
def delete_global_cgroup_config():
    try:
        if os.path.exists('/sys/fs/cgroup/cpu/qtglobal'):
            os.system('sudo cgdelete -g cpu:qtglobal')
            system_log.info('删除全局CPU CGroup控制组成功')
    except BaseException:
        system_log.error('删除全局CPU CGroup控制组失败，错误原因：{}'.format(get_traceback_message()))
        return None
def add_process_to_global_cgroup(user_id: str, pid: str):
    try:
        if GLOBAL_CPU_SWITCH == 1:
            os.system('sudo echo {} > /sys/fs/cgroup/cpu/qtglobal/tasks'.format(pid))
            system_log.info('用户 {} 进程 {} 添加至全局CPU CGroup控制组成功'.format(user_id, pid))
    except BaseException:
        system_log.error('用户 {} 进程 {} 添加至全局CPU CGroup控制组失败，错误原因：{}'.format(user_id, pid, get_traceback_message()))
